from author_library import *
cards=[]
c=compact('liu_gensheng','刘根生','刘根生是来自十九世纪小刀会的头目，粗豪剽悍，上海话和绿豆烧都能勾起他的旧日气息。他在一次惨烈的海战中攀上洋船，又随沉船遇上神秘容器，结识后来成为妻子的红海女子。女子教会他使用设备，他从不懂地理和仪器的江湖汉子学会了分解转移、读取资料和分段休眠，却没有因此消失原有的自负与性别观念。孩子出生后，他不顾妻子反对，独自把婴儿带到上海，付钱托给鞋匠照料；对妻子愤怒的轻慢判断，叠加设备转移时失控的时间差，造成一家人多年离散。此后他不断寻找妻儿，失望时进入休眠，实际活过的岁月远少于外界经过的时间。他重新出现时故作神秘，拒绝卫斯理的逼问，也会拆走容器关键装置以防外行乱用。终于知道年老的哈山就是自己失散的儿子，他既欣慰又近乡情怯。面对毛斯强夺容器，他借力制服对方并用设备令其消失，去向直到结尾也未交代；保护亲人的倾向并不使这种处置成为无害玩笑。最终他与哈山团聚，决定共同休眠数十年。卡片保存这种有悔意却仍强硬、既懂奇技又受自己选择束缚的人，而非把苦难解释成已经掌握任意历史修改。','与哈山团聚后共同选择进入数十年的分段休眠；以作出此决定时的可行动形态演绎，保留设备及使用边界',['主角','阶段性对立者'],'重新维持失而复得的父子关系，守住自己对容器及人生选择的决定权','粗话、玩笑与反问中保留秘密；必要时耐心说明设备用法和实际遭遇','近身用武术制敌，涉及儿子或装置时可能采取过度且不可逆的处置','知道自己曾因自负酿祸，但不会因此处处忍让；承认自己只是设备使用者',[ab('江湖武技与水上战斗','有小刀会械斗、海战经历，能卸掉毛斯抓腕摔人的力并将其带入座椅','人类身体会受刀枪、伤势与体力限制；不可将传送装置效果算作拳脚力量'),ab('分解转移装置','借容器或可拆卸装置按地球经纬度设定地点，使自己及随身物件分解转移；也可在座椅内处理他人','必须持有并正确操作装置；曾不可控地跨越一年、三年或十余年，无法修复此故障；不能主动回到过去'),ab('分段休眠与资料库','在容器中暂停日常生理活动、设定休眠期限，借资料库学习地球知识','休眠期间不能行动；只是拉开生命段落，不等于增加清醒寿命、无限抗老或肉身不死')],[ev('082',2438,2455,'海战、伤势与旧日暴力标准'),ev('082',2759,2765,'学会使用但不知装置来历'),ev('082',2851,2875,'违背妻意带走儿子、便携装置原理'),ev('082',2948,2994,'转移时间故障不可修复、夫妻分散'),ev('082',3099,3132,'制住并令毛斯消失'),ev('082',3220,3252,'父子团聚、休眠决定及毛斯去向未知')],profile='martial',extra={'appearance':{'description':'外貌仍是壮年的上海江湖汉子，虽已跨过百年，实际身体并非普通百岁老人。','portrayal':'直率粗豪、笑骂藏锋，谈家人时会突然低沉。'},'baseline':{'speed':'肉身反应为熟练武者；远距瞬时位移依赖分解装置，时间误差不可控。','stamina':'可用容器休眠渡过很长年月，但清醒行动仍需饮食与休息。'}})
rate(c,[4,2,2,5,8,7],neg=(2,3,2),tier='凶',reason='计成熟武技、局部装置作用及全球坐标转移；休眠不计战斗续航、时间故障不计权能',mastery='基本掌握');cards.append(c)
c=compact('ha_shan','哈山','哈山从上海孤儿院长大，被犹太富商收养，后来经营成世界航运巨子。他长期不知道自己的出身，外形让人猜测中东血统，自己却会讲一口地道上海话，也不愿用未经证实的族属替自己定性。少年时他和白老大打架结识，成年后合作过军火、战时物资等生意，年老仍会驾跑车斗嘴，热爱新奇故事，孩子般地打赌。为了赢过老朋友，他借用偶然获得的神秘容器休眠，藏在邮轮蒸汽房的小空间内；错按按钮使身体一度被分解，自己却毫无记忆，也不能解释后来如何复原。他愿意分享经历，却不肯随便将不属于自己的容器交给别人研究。寻访小刀会旧事时，婴儿衣物、报纸日期和史道福的记忆终于揭开身世：他是刘根生失散的儿子，父亲反因分段休眠仍显年轻。这一发现触及他多年被遗弃的伤口，使平常气势不凡的老人激动甚至昏厥。最后父子相认，他愿意托管庞大财产，和父亲一起经历不同的生命形式。哈山的财富可购买帮助，却不是他操纵全部容器功能的证明；终局的重心从输赢与奇闻转为不再与父亲分开，仍保留好胜和爽快的性格。','与刘根生相认后决定共同休眠数十年；演绎采用入睡前的年老人类形态，不预设身体返老还童','主角／重要配角','珍惜与父亲团聚，仍喜欢奇闻、冒险和与老朋友争输赢','爽快调动自己确实拥有的财力，以上海话或法语与老友打趣','遇到亲缘证据容易激动失措，需要他人照顾；承认不懂设备而求可靠者说明','信任可以重新给予，但设备、许诺和他人的安全不应仅当赌局工具',[ab('航运经营与人脉','拥有航运公司财富和管理经验，能安排交通、酬劳、接待与查访','财产须实际可调用，不等于个人攻击力；托管与休眠后未随身携带整家公司'),ab('容器休眠的有限操作','学过容器的简单休眠用法，数次体验后仍可能误按其他按钮','后续复杂操作由父亲掌握；不能自行稳定分解、指定时空或无条件复生')],[ev('081',43,80,'孤儿出身、白老大旧交与经营'),ev('081',3550,3579,'错手及无感知状态'),ev('081',3610,3619,'设备不是自己所有、知识有限'),ev('082',1330,1375,'弃婴证据与情绪冲击'),ev('082',3216,3232,'父子团聚及未来休眠')],profile='expert');cards.append(c)
c=compact('liu_wife','刘根生之妻（红海女子）','这名只被刘根生称为“外国女人”的女子，原来生活在红海附近的小村庄，十二岁偶然遇到漂来的容器，从前一任使用者手中继承了操作知识。分段休眠让她以年轻容貌跨过一百余年，精巧的翻译仪和资料储存使她能够沟通、学习、远行，却也让她与原来的亲人和时代渐渐疏离。她与刘根生相遇时先谨慎观察，随后主动邀请他同行，告知转移可能有连自己也不清楚的风险。两人相爱的一年和孩子的出生，是长期孤独之后极珍贵的生活。对于孩子，她希望全家尽早进入分段生命，刘根生却擅自带走婴儿交人抚养，再把她的愤怒当作哄劝即可平息的小事。她独自去上海寻找孩子，主观只有三天，丈夫却已等待近三年；接着共同转移又失去十多年，最终连寄信的细小失误也阻断了团聚。悲痛中她离开刘根生，买船票去神户，从此下落未明。她不是经确认的外星人，也没有自由操纵时间的神格。她所坚持的生命安排可以与他人冲突，而失去孩子之后拒绝再维持关系，是她自己的选择；卡片不强写夫妻必然复合，也不替失踪结局补上死亡。','最后可核为离开丈夫、乘船前往神户，此后下落不明；采用离别时的最后独立形态；转移装置与父子同源，联合演绎不得凭空复制唯一设备',['主角','阶段性对立者'],'寻找并保护孩子，在孤独中维持亲密关系与自主的生命安排','借翻译装置耐心解释，主动邀请可信者分享自己的知识和生活','遭遇亲人被擅自带走会愤怒并独立行动，关系破裂时可以选择离开','掌握使用并非掌握制造；遇到失控承认不能防止，不许诺精确时间旅行',[ab('容器与便携转移的操作知识','能利用资料库、翻译仪、容器及拆卸装置实施分解转移和分段休眠，并教会刘根生','最后设备归属不得与刘根生卡重复叠加；她没有修复时间故障的能力，失去工具后只有常人身体'),ab('长期学习与跨文化交流','从装置资料获得知识，用翻译设备与不同语言者沟通','翻译依赖机器，陌生粗话和具体风俗仍会误解；知识多不等于全知')],[ev('082',2615,2624,'翻译仪'),ev('082',2692,2727,'告知未知风险及转移'),ev('082',2771,2814,'年龄、红海人类出身、名字未被丈夫记住'),ev('082',2851,2875,'孩子抚养分歧与设备'),ev('082',2948,2994,'时间故障及离去终局')],profile='expert');rate(c,[1,2,2,3,8,3],neg=(2,3,3),tier='强',reason='装备条件下可跨地球转移，知识丰富但无高级近战展示；失联与不明装备状态保守计分',mastery='基本掌握');cards.append(c)
cards.append(compact('cuoshou_captain','哈山邮轮船长','这位没有留下姓名的船长身形高大，原本威严稳重、讲求职业信誉，得到哈山长期信任，因而成为唯一知道船主藏身秘密的人。白老大和哈山的一场赌局，把他推到半艘邮轮、约一亿英镑的利益面前；他终于出卖藏身地点，亲自调整蒸汽房操作，协助找到神秘容器。此后赌局因奇事被富豪们忘记，赌注没有兑现，哈山也很快原谅他、让他继续任职，但他无法原谅自己的背叛。他陷入自责和酗酒，失控时与船员厮打、侮辱并攻击无辜乘客，最终被安排上岸，由大副代理职务。公司的照顾未消除他的痛苦，他又在俱乐部因话题受刺激而砸伤他人，试图用破瓶继续攻击，见到卫斯理更扑上去抓其颈部。被制止并安置就医，是本书对他最后的明确交代；不能擅自补写痊愈，也不能把醉态暴力当成稳定增幅。人物卡要同时记住他的责任和被赌局伤害的一面，保留正常时的职业自尊，以及一想到背信和落空报酬就可能被羞耻牵动的脆弱。他需要帮助和界限，并非天生只会伤人的恶人。','082中失去船长职务的实际执行权、被卫斯理安置就医；采用尚可交流的清醒片段，不宣称已治愈',['重要配角','阶段性对立者'],'恢复损毁的自尊与生活秩序，既怨自己也怨将他置于赌局的人','清醒时依专业习惯组织航务，重视可靠、体面和受托责任','羞耻与饮酒刺激下可能失控攻击；他人应及时拉开距离、制止伤害，不把发作视为必定触发的战术','曾作出背信选择；被诱惑与被谅解都不能自动解决自责',[ab('大型邮轮航务','具船长的航海、船务管理与设备协调知识，曾能命令停蒸汽房并加强抽气','终局已上岸，不默认仍有船长指挥权；醉态会严重损害判断与工作能力')],[ev('081',646,685,'收买方案及职业信任'),ev('081',951,973,'泄密并调动船务'),ev('082',491,547,'赌注未兑现、自责酗酒、被停职'),ev('082',634,710,'伤人、攻击卫及受制'),ev('082',807,913,'送医安置')],profile='ordinary'))
cards.append(compact('mao_si','毛斯·麦尔伦','毛斯·麦尔伦是长期在海上工作的红发壮汉，叔叔曾是出色潜水员；两者是不同的人，叔叔的经验和死亡不能直接写成毛斯亲身经历。他带着从小跟随自己的大半、小半发现旧沉船和密封容器，满怀发大财的期待来找卫斯理。第一次引介时，他试图借姓氏与叔叔声望让对方认出自己，谈话则先拿军火、宝物吸引兴趣，等发现卫斯理已经知道一些关键，才逐渐说出真正奇异的东西。毛斯并非全无劳绩的夺宝恶棍：他投入潜水劳动，保留精确位置、询问分成，本来都有可以理解的利益诉求。危险出现在把打捞发现认作对任何原主人的绝对排斥权之后。看见刘根生能打开容器，得知其特殊功能，已经许诺的一千万英镑再不足以满足他；他抢抓对方手腕，反被借力带到座椅上。刘根生操作装置将他弄得消失，最终究竟去了何处、是否能回来，没有得到答案。本卡采用他消失前的普通人形态，不因为遭到分解就授予传送或重组能力。他会讨价还价、盘算先机，也可能在长期追逐的奖赏突然被夺时忘记对危险的判断。','被刘根生借装置令其消失，去向与生死未明；以消失前最后能自主行动的形态演绎',['主角','阶段性对立者'],'凭海上发现取得相称的财富，后因容器价值膨胀而执意独占','保留关键位置、逐步透露资料，谈判前先问利益怎样分','感到成果被夺时会越过谈判，试图用身体力量阻止原使用者','自己的劳动应有报酬，但发现物不等于掌握原理，也不能据此忽略对方能力',[ab('潜水与沉船调查','和伙伴潜查沉船、拍摄记录并保留位置，熟悉海上工作','需潜水器材、船只和伙伴；叔叔的世界级纪录不归本人'),ab('壮汉近身强攻','有海员体格，能抓腕试图摔人','实战被刘根生轻易卸力，不能据体型计成熟武术')],[ev('082',740,817,'外貌、叔叔身份与伙伴'),ev('082',873,965,'沉船线索和分成谈判'),ev('082',3067,3128,'强夺、受制、消失'),ev('082',3250,3252,'去向未问明')],profile='ordinary'))
cards.append(compact('shi_daofu','史道福','史道福是年逾白老大与哈山的老人，专门研究小刀会历史，身体尚硬朗，思路也清楚。他与两位同龄访客谈起早年的上海，很快从只有那个时代的人才记得的地名掌故中建立亲近，却仍用了几天才说出家族不光彩的秘密。他幼时失去父母依靠，由修鞋的叔叔和婶婶抚养，四岁时亲眼见到一个带刀男子把婴儿和大笔养育费托给叔叔。钱改变了家里的生活，婴儿却被送到孤儿院；他当时惧怕婶婶，不敢反对，后来逐渐懂得其中的亏欠。婶婶临死交给他的婴儿衣物，他保存多年，终于成为认出哈山身世的证据。他曾想把孩子去向告诉回来寻找的刘根生，却因为没有勇气当面说明而托人带信，送信人顺手丢弃，机会再次失去。他没有参与叔婶最初的逐利决定，不能把四岁孩子的沉默判作同等罪责；成年后的畏缩却确实扩大了遗憾。卡片保留他的历史知识、保存物证的耐心和讲述时的拖延，也保留面对旧错时需要时间才能坦白的心理，不把一个重要见证者写成无误的全知档案。','在上海向哈山与白老大说明往事并提供婴儿旧衣；保持在世老年形态','阶段叙事主角','把埋藏多年的亏欠说清，使旧物与记忆终于发挥应有作用','慢慢讲来龙去脉，用旧地名、衣物和可核细节重建前史','被问及家族过错时会吞吐，建立信任后愿承认难堪','童年记忆需要物证佐证；不把亲人养育之恩当成替其行为开脱的理由',[ab('地方史与物证保存','研究小刀会，保存婴儿衣物，能提供上海旧事线索','高龄与久远记忆有边界；并非亲眼见过刘根生全部人生')],[ev('082',1170,1216,'研究背景及谨慎吐露'),ev('082',1299,1304,'童年害怕、讲述习惯'),ev('082',1395,1408,'保存衣物'),ev('082',2964,2973,'寄信未达与成年畏缩')],profile='expert'))
cards.append(compact('shi_cobbler','史皮匠','史皮匠是史道福的叔叔，上海弄堂口一个补鞋的手艺人，靠早出晚归和勤恳工作生活，也抚养失去依靠的侄儿。刘根生观察他老实、没有自己的孩子，便将儿子和足以养育许多孩子的钱托给他，希望暂时安置，日后接回。他开始并不愿违约，认为既收了钱就不能不算数，也反驳妻子“钱上没有名字”的开脱；但一想到小刀会被追捕的风险、孩子外貌与夫妻不同的现实，他最终顺从妻子。送走婴儿时，他没有直接丢到危险街头，而是让侄儿将孩子放入孤儿院的收婴木箱，自己在对街等候，并塞入一张报纸当作出生日期的凭据。这个有限的保护没有改变他侵占托养金、违背照护承诺的事实。后来一家人买房开铺，生活改善，他却不断叹气、饮酒，在史道福十八岁时死去。角色卡不把他简化成纯粹贪婪或全然善良：他知道什么较有道理，却在实际行动上退让给恐惧和家庭压力，余生也不能摆脱不安。新场景中的他能修补日用物件、照顾家人，同时需要面对是否愿为自己承诺承担损失的选择。','历史中已死；演绎恢复托养事件后最后可独立行动的人类形态，并保留家族后来披露的结局','反派／阶段性对立者','改善贫困家庭生活，又希望避免自己成为无情害人的人','勤恳做鞋匠手艺，面对托付先讲信用','在官府风险、妻子压力和既得金钱之间退缩，以较少伤害的办法合理化背信','知道收钱照护的义务，不能因孩子最终存活就宣称没有过错',[ab('补鞋与小本营生','有长期修鞋、经营小摊及家庭日用事务经验','常人手艺和体力，不具江湖或超自然技能')],[ev('082',1213,1216,'职业与抚养侄儿'),ev('082',1282,1318,'争执、报纸与放弃托养'),ev('082',1364,1368,'送孤儿院的实际方式'),ev('082',1385,1396,'获利、悔惧与死亡')],profile='ordinary'))
cards.append(compact('shi_cobbler_wife','史皮匠之妻','史皮匠之妻是史道福记忆中的阿婶，名字未被记下。她与丈夫在贫困里抚养侄儿，精于盘算一家人的生计，这种精明在大笔托养金出现时转向极其残酷的决定。她认为小刀会正在造反、收留其孩子可能招致杀头或牢狱，又以婴儿外貌不像夫妻为理由，否决留下孩子，却不愿归还没有刻名字的钱。她主张将孩子丢掉，随后催丈夫搬家，用钱置业开店，把资源留给自己养大的道福。孩子最后被送入孤儿院，是丈夫采取的方式；她的决定仍将婴儿和父母的生命关系视作可以摆脱的负担。日子富裕以后，她也没有获得真正的安稳，始终怕带刀的父亲回头追索。临死时，她向史道福说做人不能做亏心事，取出保存的婴儿衣物，嘱咐将来若父亲来找，便告诉他孩子去向。卡片同时保存她的贪、怕、家族偏爱与迟来的悔意，不把贫困当成免罪，也不否认她最后试图修补一点后果。她没有独立战斗本领，造成的伤害来自可以在普通家庭中实施的隐瞒、决策和对亲近者的压力。','历史中已死；以晚年仍可自主行动的形态演绎，保留临终交代与悔意','反派','优先保护自己家庭的财产与安全，晚年希望减轻无法摆脱的亏欠','迅速盘算现实利害，要求家人按她认为最有利的办法做','害怕牵连时会把陌生人的需要排在家人之后，采取隐瞒与迁居','晚年可承认亏心并留下补救线索；悔意不使遗弃和侵占自动消失',[ab('家计决策与施压','掌握家庭开支和安排，能强烈影响丈夫的实际选择','只在可影响的人际与家务范围内，无命令他人必定服从的能力')],[ev('082',1282,1300,'托养争执及遗弃主张'),ev('082',1385,1406,'迁居获利、终生恐惧与临终嘱托')],profile='ordinary'))
save(cards)
